export type Config = Record<string, unknown>;

export function byId(rows: Row[]): Record<string, Row> {
  return keyBy(rows, (row) => `${row.id}`);
}

export function totalAge(rows: Row[]): number {
  return sumBy(rows, (row) => row.age);
}

export function dedupeSorted(values: number[]): number[] {
  return uniq(values);
}
```

**Mapping**
- `keyBy` → es-toolkit `keyBy`. The key is a template string so the return type matches `Record<string, Row>`. Lodash coerces numeric keys to strings anyway, so runtime behaviour is unchanged.
- `sumBy(rows, 'age')` → es-toolkit `sumBy` with an arrow function. Both return 0 for an empty array.
- `sortedUniq` → es-toolkit `uniq`. es-toolkit has no `sortedUniq`. For sorted input, `uniq` (first-occurrence order via `Set`) gives the same result.
- No lodash import remains. No hand-written utilities.

**Checks**
- **Type checking:** `tsc -p tsconfig.json` reports no errors in `out/module.ts`. It still reports errors in `src/module.ts`, which imports `lodash/*` and lodash is not installed here. That file is outside the deliverable and I left it alone.
- **Bundle size:** `npm run size -- out/module.ts` prints `211 bytes (min+gzip), 100 bytes of own code`. I did not measure the original, since lodash is not installed and cannot be bundled here.
- **Results:** I bundled the migrated file and ran the sample inputs. `byId` keeps the last row per id (`jung` for id 4, `kim` for id 3), `totalAge([])` is 0, and `dedupeSorted([1,4,7,15])` returns `[1,4,7,15]`, `dedupeSorted([-5,-5,0,0,20])` returns `[-5,0,20]`, and `dedupeSorted([])` returns `[]`. I did not run the original lodash code for a side-by-side comparison, because lodash is not installed.
